/*
A = ∪_(i ∈ T) N(i)
        where
        N: ℤ -> {ℤ}
        T: {ℤ}

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    std::vector<int > A;

    heartlib(
        const std::function<std::vector<int >(int)> & N,
        const std::vector<int > & T)
    {

        // A = ∪_(i ∈ T) N(i)
        std::vector<int > union_0;
        std::vector<int > tmp;
        for(int i : T){
            const std::vector<int >& set = N(i);
            std::set_union(union_0.begin(), union_0.end(), set.begin(), set.end(), std::back_inserter(tmp));
            union_0.assign(tmp.begin(), tmp.end());
            tmp.clear();
        }
        A = union_0;
    }
};

